import json,csv
from pathlib import Path
from datetime import datetime,timezone
base=Path('/workspace/scratch/7feb9690b71f/SA08_work')
dest=base/'work/late'
src={}
for p in dest.glob('*entries_source.json'):
 for e in json.loads(p.read_text()):src[e['entry_id']]=e
items=[];entries=[]
def ids(s):
 return [f'MPL_136_{"235-281" if z[0]=="D" else "282-327"}#{int(z[1:])}' for z in s.split()]
def item(n,s,kind,scans,lines,words,statement,reconstruction,reason,check='agrees',overrides=None):
 ii=f'SA08-{n}';ss=ids(s)
 items.append(dict(id=ii,sources=ss,kind=kind,cote='136',scans=scans,lines=lines,his_words=words,statement=statement,reconstruction=reconstruction,check=check,check_reason=reason))
 for k,e in enumerate(ss):
  verdict=('kept' if k==0 else 'merged') if check=='agrees' else 'corrected'
  er=reason
  if overrides and e in overrides:verdict,er=overrides[e]
  entries.append(dict(entry_id=e,item_id=ii,verdict=verdict,reason=er))

